import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.CJEq1BAB.js";var c=JSON.parse(`{"title":"First administrator","description":"","frontmatter":{"title":"First administrator","covers":{"screens":[],"stories":["US-013","US-015","US-016","US-017"]}},"headers":[],"relativePath":"setup/first-administrator.md","filePath":"setup/first-administrator.md"}`),l={name:`setup/first-administrator.md`};function u(i,c,l,u,d,f){let p=s(`Screenshot`);return e(),o(`div`,null,[c[0]||=r(`<h1 id="first-administrator" tabindex="-1">First administrator <a class="header-anchor" href="#first-administrator" aria-label="Permalink to “First administrator”">​</a></h1><p>A new instance has no account. You create the first one – the local <strong>system admin account</strong> – with a one-time setup token that only someone with access to the server can read. No identity provider is needed for this.</p><h2 id="read-the-setup-token" tabindex="-1">Read the setup token <a class="header-anchor" href="#read-the-setup-token" aria-label="Permalink to “Read the setup token”">​</a></h2><p>As long as no system admin account exists, the backend writes a setup token to the file <code>/run/oea/setup-token</code> inside the container and logs where to find it. The token itself never appears in the log or in an API response:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /run/oea/setup-token</span></span></code></pre></div><p>Only the OEA user inside the container can read the file, so you need access to the server or the container – nobody can fetch the token over the network. The token is valid for 24 hours. Every start of the backend issues a new token and invalidates the previous one; if your token has expired, restart the backend and read the file again. After a successful bootstrapping, the backend deletes the file.</p><h2 id="create-the-system-admin-account" tabindex="-1">Create the system admin account <a class="header-anchor" href="#create-the-system-admin-account" aria-label="Permalink to “Create the system admin account”">​</a></h2><p>Open the setup page <code>/setup</code> of the web interface (the start page shows <em>Setup required</em> while no account exists) and fill in:</p>`,8),a(p,{name:`setup-required`,alt:`Start page of a new instance with the notice Setup required`}),c[1]||=r(`<table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Setup token</td><td>the token from the file</td></tr><tr><td>Login name</td><td>the login name of the system admin account</td></tr><tr><td>Password, Repeat password</td><td>12 to 128 characters</td></tr><tr><td>Instance slug</td><td>short, stable name of the instance; it is used in external references (<code>urn:oea:&lt;slug&gt;:&lt;id&gt;</code>) and cannot be changed later</td></tr></tbody></table>`,1),a(p,{name:`setup-form`,alt:`Setup form with token, login name, password and instance slug`}),c[2]||=n(`p`,null,[t(`Choose `),n(`em`,null,`Create system admin account`),t(`. The page confirms the account and the instance slug.`)],-1),a(p,{name:`setup-done`,alt:`Confirmation of the created system admin account`}),c[3]||=r(`<p>Through the API you send the same data to <code>POST /api/v1/setup</code>; <code>GET /api/v1/setup/status</code> tells you whether setup is still required.</p><ul><li>Bootstrapping works exactly once. If two attempts arrive at the same time, exactly one succeeds. Every further attempt is rejected, and the token is no longer valid; the existing account stays unchanged.</li><li>A missing, wrong or expired token is rejected without creating an account.</li><li>Every completed and every rejected attempt is recorded in the audit trail with time, mode <code>local</code> and result: <code>system.bootstrapped</code> (result <code>success</code>, attributed to the new system admin account) and <code>system.bootstrap-rejected</code> (result <code>denied</code>, with the reason, for example <code>invalid-setup-token</code>). Neither the token nor the password is recorded. With these entries you can show when and how the first privileged access to the instance came into existence (see <a href="./../administration/operations#verify-the-audit-trail">Verify the audit trail</a>).</li></ul><h2 id="the-setup-phase" tabindex="-1">The setup phase <a class="header-anchor" href="#the-setup-phase" aria-label="Permalink to “The setup phase”">​</a></h2><p>After the bootstrapping, the instance is in its <strong>setup phase</strong>: the system admin account logs in with login name and password only. The setup phase ends with the first action that gives another identity access – the first identity binding or IdP group mapping (see <a href="./../administration/identity-providers">Identity providers and persons</a>). This action needs a second factor:</p><ol><li>Log in with the system admin account (see <a href="./../usage/login">Logging in</a>).</li><li>Open <em>Profile</em> and choose <em>Set up a second factor</em>, then <em>Set up authenticator app</em>. Scan the QR code with your authenticator app and enter the code from the app. The session is now confirmed with the second factor.</li><li>Create the first identity binding or group mapping. This ends the setup phase for good (audit event <code>system.setup-phase-ended</code>).</li></ol><p>From then on, every login of the system admin account needs a code of the authenticator app.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>During the setup phase, only the password and the login throttling protect the instance. End the setup phase before you make the instance publicly reachable.</p></div><p>The system admin account administers the instance (identity providers, persons, roles). It does not work with architecture content and cannot import metamodel packages; these tasks belong to persons with the corresponding roles (separation of duties, see <a href="./../administration/roles-and-permissions">Roles and permissions</a>).</p>`,8)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};